"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CONCENTRATION_CURVE,
  DOWNSTREAM_RISK,
  HEADLINE,
  HHI_BANDS,
  INVESTMENT_CONTEXT,
  SMELTER_STRESS,
  SOURCE_NOTE,
  STAGE_FLIPS,
  TOP_K_LADDER,
  VINTAGE_DELTA,
  filterCommodities,
  fmtDelta,
  fmtHhi,
  fmtPct,
  hhiBand,
  producerScoreboard,
  sectorExposures,
  type Direction,
  type Sector,
  type Stage,
} from "@/data/chokepoint-commodities-concentration-2026q3-data";

// viz-types: vintage delta bars, Lorenz area+line, mine???plant slope, HHI donut, producer bars, risk??share scatter | layout: default

type ViewId = "delta" | "ladder" | "flips" | "risk";
type Metric = "top1" | "top3" | "hhi";

const ROSE = "#f43f5e";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";
const TEAL = "#14b8a6";
const SLATE = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function ChokepointCommoditiesConcentration2026q3Dashboard() {
  const [view, setView] = useState<ViewId>("delta");
  const [metric, setMetric] = useState<Metric>("top1");
  const [stage, setStage] = useState<Stage | "all">("all");
  const [direction, setDirection] = useState<Direction | "all">("all");
  const [sector, setSector] = useState<Sector | "all">("all");
  const [showEqual, setShowEqual] = useState(true);

  const filtered = useMemo(
    () => filterCommodities({ stage, sector, direction }),
    [stage, sector, direction],
  );

  const ladderBars = useMemo(() => {
    return [...filtered]
      .map((c) => ({
        ...c,
        value:
          metric === "top1"
            ? c.top1SharePct
            : metric === "top3"
              ? c.top3SharePct
              : c.hhi,
      }))
      .sort((a, b) => b.value - a.value);
  }, [filtered, metric]);

  const vintageBars = useMemo(() => {
    return VINTAGE_DELTA.filter((d) => {
      if (stage !== "all" && d.stage !== stage) return false;
      if (direction !== "all" && d.direction !== direction) return false;
      return true;
    }).slice(0, 12);
  }, [stage, direction]);

  const producers = useMemo(() => producerScoreboard(filtered), [filtered]);
  const sectors = useMemo(() => sectorExposures(filtered), [filtered]);

  const hhiDonut = useMemo(() => {
    return HHI_BANDS.map((b) => ({
      ...b,
      count: filtered.filter((c) => hhiBand(c.hhi).id === b.id).length,
    })).filter((b) => b.count > 0);
  }, [filtered]);

  const flipSeries = useMemo(
    () =>
      STAGE_FLIPS.flatMap((f) => [
        {
          metal: f.metal,
          point: "Mine",
          top1: f.mineTop1,
          leader: f.mineLabel,
        },
        {
          metal: f.metal,
          point: f.plantStage,
          top1: f.plantTop1,
          leader: f.plantLabel,
        },
      ]),
    [],
  );

  const riskScatter = useMemo(
    () =>
      filtered.map((c) => ({
        shortLabel: c.shortLabel,
        top1: c.top1SharePct,
        hhi: c.hhi,
        reliance: c.usNetImportReliancePct,
        fill: c.fill,
        z: Math.max(40, c.substitutionDifficulty * 30),
      })),
    [filtered],
  );

  const metricLabel =
    metric === "top1"
      ? "Top-1 share %"
      : metric === "top3"
        ? "Top-3 share %"
        : "HHI";

  return (
    <div
      className="space-y-6"
      data-viz="chokepoint-commodities-concentration-2026q3"

    elecFossilSharePct: 62,
    elecRenewSharePct: 38,
    elecNuclearSharePct: 0,
    importDependencePct: -140,
    tradeStance: "net-exporter",
    confidence: "estimated",
    note: "Coal + LNG export surplus dwarfs domestic TPES",
  },
  {
    id: "germany",
    label: "Germany",
    shortLabel: "Germany",
    iso: "DE",
    region: "Europe",
    primaryEj: 12,
    oilSharePct: 34,
    gasSharePct: 25,
    coalSharePct: 18,
    nuclearSharePct: 1,
    hydroSharePct: 2,
    otherRenewSharePct: 20,
    elecFossilSharePct: 42,
    elecRenewSharePct: 55,
    elecNuclearSharePct: 0,
    importDependencePct: 65,
    tradeStance: "net-importer",
    confidence: "estimated",
  },
  {
    id: "france",
    label: "France",
    shortLabel: "France",
    iso: "FR",
    region: "Europe",
    primaryEj: 9,
    oilSharePct: 30,
    gasSharePct: 15,
    coalSharePct: 3,
    nuclearSharePct: 36,
    hydroSharePct: 5,
    otherRenewSharePct: 11,
    elecFossilSharePct: 8,
    elecRenewSharePct: 28,
    elecNuclearSharePct: 64,
    importDependencePct: 45,
    tradeStance: "net-importer",
    confidence: "estimated",
    note: "Nuclear cuts electricity fossil share far below primary oil/gas dependence",
  },
  {
    id: "uk",
    label: "United Kingdom",
    shortLabel: "UK",
    iso: "GB",
    region: "Europe",
    primaryEj: 7,
    oilSharePct: 36,
    gasSharePct: 35,
    coalSharePct: 3,
    nuclearSharePct: 7,
    hydroSharePct: 1,
