                    formatter={(v: number) => fmtPct(v, 1)}
                  />
                  <Area
                    type="monotone"
                    dataKey="sharePct"
                    fill={AMBER}
                    fillOpacity={0.25}
                    stroke={AMBER}
                    strokeWidth={2}
                    name="Cumulative"
                  />
                  {showEqual && (
                    <Line
                      type="monotone"
                      dataKey="equalPct"
                      stroke={SLATE}
                      strokeDasharray="6 4"
                      dot={false}
                      name="Equal"
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Top demand countries"
            subtitle="Share of world TPES (EJ) ??? Rest of world excluded"
          >
            <div className="h-[340px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={demandBars}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
