          </ChartCard>

          <ChartCard
            title="Stance mix"
            subtitle="Count of tracked systems by trade stance"
          >
            <div className="h-[240px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={[
                      {
                        name: "Net importer",
                        value: IMPORT_EXPOSURE.filter(
                          (r) => r.tradeStance === "net-importer",
                        ).length,
                        fill: ROSE,
                      },
                      {
                        name: "Net exporter",
                        value: IMPORT_EXPOSURE.filter(
                          (r) => r.tradeStance === "net-exporter",
                        ).length,
                        fill: TEAL,
                      },
                      {
                        name: "Balanced",
                        value: IMPORT_EXPOSURE.filter(
                          (r) => r.tradeStance === "balanced",
                        ).length,
                        fill: SLATE,
                      },
                    ].filter((d) => d.value > 0)}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={90}
                  >
                    {[
                      ROSE,
                      TEAL,
                      SLATE,
                    ].map((c, i) => (
                      <Cell key={i} fill={c} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
