                  <Bar dataKey="top2" stackId="a" fill={AMBER} name="Top-2" />
                  <Bar dataKey="top3" stackId="a" fill={SKY} name="Top-3" />
                  <Bar
                    dataKey="rest"
                    stackId="a"
                    fill={SLATE}
                    name="Rest"
                    radius={[4, 4, 0, 0]}
